#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Full

Viewpoint {
  position 0 0 6
}

NavigationInfo {
  headlight FALSE
}

DEF TIM TimeSensor {
  cycleInterval 1.2
  loop TRUE
}

DEF INT ScalarInterpolator {
  key [
    0,
    0.5,
    1
  ]
  keyValue [
    0.2,
    1,
    0.2
  ]
}

Transform {
  translation -1.4 0.8 0
  children Shape {
    appearance Appearance {
      shaders DEF CS ComposedShader {
        initializeOnly SFColor tint 0.9 0.4 0.2
        initializeOnly SFFloat amount 1
        initializeOnly SFBool  flag FALSE
        initializeOnly MFFloat arr [
          0,
          0
        ]
        initializeOnly SFInt32 mode 0

        language "GLSL"
        parts [
          ShaderPart {
            url "data:x-shader/x-vertex,
attribute vec4 x3d_Vertex;
attribute vec3 x3d_Normal;
attribute vec4 x3d_TexCoord0;
attribute vec4 x3d_Color;
uniform mat4 x3d_ProjectionMatrix;
uniform mat4 x3d_ModelViewMatrix;
uniform mat3 x3d_NormalMatrix;
varying vec3 vN;
varying vec3 vP;
varying vec2 vT;
varying vec4 vC;
void main()
{
   vec4 p = x3d_ModelViewMatrix * x3d_Vertex;
   vP = p.xyz;
   vN = normalize (x3d_NormalMatrix * x3d_Normal);
   vT = x3d_TexCoord0.st;
   vC = x3d_Color;
   gl_Position = x3d_ProjectionMatrix * p;
}
"
          }
          ShaderPart {
            type "FRAGMENT"
            url "data:x-shader/x-fragment,
precision mediump float;
varying vec3 vN;
varying vec3 vP;
varying vec2 vT;
varying vec4 vC;
uniform vec3 tint;
uniform float amount;
uniform bool flag;
uniform float arr [2];
uniform int mode;
void main()
{
   vec3 c = tint * (0.3 + 0.7 * abs (vN.z)) * amount + vec3 (arr [0], arr [1], 0.0);
   if (flag) c = c.gbr;
   if (mode == 1) c *= 0.5;
   gl_FragColor = vec4 (c, 1.0);
}
"
          }
        ]
      }
    }
    geometry Sphere {
      radius 0.6
    }
  }
}

